from random import *
import time

def ilog2(n):
	return 0 if n <= 0 else n.bit_length() - 1

def pack(pack, shamt):
	size = len(pack)
	while size > 1:
		npack = []
		for i in range(0, size - 1, 2):
			npack += [pack[i] | pack[i + 1] << shamt]
		if size & 1:
			npack += [pack[-1]]
		(pack, size, shamt) = (npack, size + 1 >> 1, shamt << 1)
	return pack[0]

def unpack(M, size, shamt):
	(s, sizes) = (size, [])
	while s > 1:
		sizes += [s]
		s = s + 1 >> 1
	ret = [M]
	for size in sizes[::-1]:
		(mask, nret) = ((1 << shamt) - 1, [])
		for c in ret:
			nret += [c & mask, c >> shamt]
		(ret, shamt) = (nret[:size], shamt >> 1)
	return ret

def poly_mul_mod(f, g, mod):
	size = min(len(f), len(g))
	shift = ((mod - 1) ** 2 * size).bit_length()
	rsize = len(f) + len(g) - 1
	h = unpack(pack(f, shift) * pack(g, shift), rsize, shift * (1 << ilog2(rsize - 1)))
	return [int(x % mod) for x in h]

def poly_inverse_mod(f, size, mod):
	assert f[0] == 1
	(deg, degs) = (size - 1, [])
	while deg > 0:
		degs += [deg]
		deg >>= 1
	f2 = f[:]
	if len(f2) < size:
		f2.extend([0] * (size - len(f2)))
	inv = [1]
	for t in degs[::-1]:
		s = t + 1 - len(inv)
		tmp = poly_mul_mod(f2[:t + 1], inv, mod)[len(inv):]
		tmp = poly_mul_mod(tmp[:s], inv[:s], mod)
		inv.extend([-v % mod for v in tmp[:s]])
	return inv

def inv(a, b):
	return pow(a, b - 2, b)
MOD = 998244353

def multiply(A):
	if len(A) == 1:
		return A[0]
	mid = len(A) // 2
	return poly_mul_mod(multiply(A[:mid]), multiply(A[mid:]), MOD)

def sum_of_powers(N, n):
	(A, B) = ([0] * n, [0] * n)
	A[0] = 1
	B[0] = N
	P = (N + 1) % MOD
	for i in range(1, n):
		A[i] = A[i - 1] * inv(i + 1, MOD) % MOD
		P = P * (N + 1) % MOD
		B[i] = (P - 1) * A[i] % MOD
	F = poly_mul_mod(B, poly_inverse_mod(A, n, MOD), MOD)[:n]
	P = 1
	for i in range(1, n):
		P = P * i % MOD
		F[i] = F[i] * P % MOD
	return F
